function renderResources(){document.getElementById('resources').innerHTML=`<div class="resource"><span class="icon">◈</span><span><small>Rice</small><b>${game.grain}</b></span></div><div class="resource"><span class="icon">◉</span><span><small>Silver</small><b>${game.gold}</b></span></div><div class="resource"><span class="icon">⚑</span><span><small>Renown</small><b>${game.fame}</b></span></div>`;document.getElementById('fame').textContent=game.fame;document.getElementById('season').textContent=`${seasons[game.season]} · ${game.year} AD`;document.getElementById('progressBar').style.width=`${Math.max(13,ownCities().length/8*100)}%`;document.getElementById('progressText').textContent=`${ownCities().length} of 8 commanderies`;document.getElementById('armyCount').textContent=ownCities().length}
function renderMap(){const layer=document.getElementById('provinceLayer');layer.innerHTML='';game.cities.forEach(c=>{const b=document.createElement('button');b.className=`province ${c.faction!=='Shu'?'enemy':''} ${game.selected===c.id?'selected':''}`;b.style.left=c.x+'%';b.style.top=c.y+'%';b.style.setProperty('--faction',factionColors[c.faction]);b.setAttribute('aria-label',`${c.name}, ${c.faction}, ${c.troops} troops`);b.innerHTML=`<span class="city-dot"></span><span class="city-label">${c.name}</span><span class="city-meta">${c.faction==='Shu'?'SHU':c.faction.toUpperCase()} · ${formatTroops(c.troops)}</span>${c.faction==='Shu'?`<span class="army">⚔ ${formatTroops(c.troops)}</span>`:''}`;b.onclick=()=>selectCity(c.id);layer.appendChild(b)});document.getElementById('mapTime').textContent=game.turn===1?'· The empire fractures':`· Year ${game.year} · Turn ${game.turn}`}
function formatTroops(n){return n>=1000?(n/1000).toFixed(n%1000===0?0:1)+'k':n}
function renderCity(){const c=city(game.selected)||city('chengdu');const friendly=c.faction==='Shu';document.getElementById('cityPanel').innerHTML=`<div class="city-title-row"><div><h2>${c.name}</h2><p>${c.terrain} · ${c.faction==='Shu'?'Your commandery':c.faction+' territory'}</p></div><span class="status-pill ${friendly?'':'enemy'}">${friendly?'Loyal':'Contested'}</span></div><div class="city-desc">“${c.desc}”</div><div class="city-stats"><div class="stat-box"><small>Garrison</small><b>${c.troops.toLocaleString()} <em>troops</em></b></div><div class="stat-box"><small>Local grain</small><b>${c.grain} <em>stores</em></b></div><div class="stat-box"><small>Prosperity</small><b>${'◆'.repeat(c.wealth)}<em>${c.wealth<4?' ◇'.repeat(4-c.wealth):''}</em></b></div><div class="stat-box"><small>Governor</small><b style="font:600 13px Georgia">${c.general}</b></div></div><div class="generals"><div class="subhead"><span>Commanding officers</span><span>${friendly?'YOUR COURT':'ENEMY COMMAND'}</span></div><div class="general-row"><div class="avatar">${c.general.slice(0,1)}</div><div class="general-info"><b>${c.general}</b><small>${friendly?'Virtuous ruler':'Garrison commander'} · ${c.terrain}</small></div><span class="general-ability">${friendly?'★ ★ ★':'★ ★'}</span></div>${friendly&&c.id==='chengdu'?'<div class="general-row"><div class="avatar">關</div><div class="general-info"><b>Guan Yu</b><small>Sworn brother · Vanguard</small></div><span class="general-ability">★ ★ ★</span></div>':''}</div>`;renderActions(c)}
function renderActions(c){const friendly=c.faction==='Shu',actions=document.getElementById('actionButtons'),note=document.getElementById('actionNote');if(friendly){actions.innerHTML=`<button class="action-btn" data-action="recruit" ${game.gold<80||game.grain<35?'disabled':''}><span class="ico">⚔</span><b>Recruit troops</b><small>+1,000 · ◉80 ◈35</small></button><button class="action-btn" data-action="develop" ${game.gold<60?'disabled':''}><span class="ico">⌂</span><b>Develop city</b><small>Prosperity · ◉60</small></button><button class="action-btn" data-action="farm" ${game.gold<35?'disabled':''}><span class="ico">❋</span><b>Improve farms</b><small>+100 grain · ◉35</small></button><button class="action-btn" data-action="march" ${c.troops<500?'disabled':''}><span class="ico">➜</span><b>March army</b><small>Choose a neighboring target</small></button>`;note.textContent=game.target?`Choose an enemy commandery on the map for ${c.name}'s army. Tap March again to cancel.`:'Gold and grain replenish each season. You may issue one order each turn.'}else{actions.innerHTML=`<button class="action-btn" data-action="attack" ${ownCities().length===0?'disabled':''}><span class="ico">⚔</span><b>Attack ${c.name}</b><small>Commit a nearby army</small></button><button class="action-btn" data-action="envoy" ${game.gold<50?'disabled':''}><span class="ico">✉</span><b>Send an envoy</b><small>Test their loyalty · ◉50</small></button>`;note.textContent='Enemy commanderies can be conquered by force or persuaded to join your cause.'}document.querySelectorAll('[data-action]').forEach(btn=>btn.onclick=()=>doAction(btn.dataset.action,c.id))}
function renderLog(){document.getElementById('logList').innerHTML=game.log.map(item=>`<div class="log-item"><span class="log-turn">Y${game.year}</span><span>${item.text}</span></div>`).join('')||'<div class="log-item">The court awaits its first dispatch.</div>'}
function render(){renderResources();renderMap();renderCity();renderLog()}
function selectCity(id){if(game.ended)return;if(game.target&&city(id).faction!=='Shu'){const source=city(game.target);game.target=null;attack(source,id);return}game.selected=id;renderMap();renderCity()}
function doAction(action,id){const c=city(id);if(action==='recruit'){game.gold-=80;game.grain-=35;c.troops+=1000;addLog(`<b>${c.name}</b> recruits 1,000 new soldiers to the banner.`);toast('Fresh troops answer the call.')}else if(action==='develop'){game.gold-=60;c.wealth=Math.min(4,c.wealth+1);addLog(`<b>${c.name}</b> grows more prosperous under your stewardship.`);toast('The city prospers.')}else if(action==='farm'){game.gold-=35;game.grain+=100;c.grain+=35;addLog(`New irrigation brings a rich harvest to <b>${c.name}</b>.`);toast('Grain stores increased.')}else if(action==='march'){game.target=game.target?null:id;game.selected=id;toast(game.target?'Select an enemy city on the map.':'March orders cancelled.');render()}else if(action==='attack'){const source=ownCities().sort((a,b)=>Math.abs(a.x-c.x)+Math.abs(a.y-c.y)-Math.abs(b.x-c.x)-Math.abs(b.y-c.y))[0];if(source)attack(source,id)}else if(action==='envoy'){game.gold-=50;const success=Math.random()<(.32+(game.fame/150));if(success){c.faction='Shu';c.troops=Math.floor(c.troops*.65);game.fame+=5;addLog(`<b>Envoy triumphs:</b> the governor of ${c.name} pledges loyalty to Liu Bei.`);toast(`${c.name} joins your cause!`)}else{addLog(`The governor of <b>${c.name}</b> rejects your offer and turns the envoy away.`);toast('The envoy returns empty-handed.')}render();checkEnd()}}
function attack(source,targetId){const target=city(targetId);if(!source||source.faction!=='Shu'||!target||target.faction==='Shu')return;const commitment=Math.floor(source.troops*.62);if(commitment<500){toast('Not enough soldiers to march.');return}source.troops-=commitment;const power=commitment*(.72+Math.random()*.55),defense=target.troops*(.72+Math.random()*.55);if(power>defense){target.faction='Shu';target.troops=Math.max(450,Math.floor((commitment+target.troops)*.26));game.fame+=7;game.grain=Math.max(0,game.grain-35);addLog(`<b>Victory at ${target.name}!</b> ${source.general} captures the commandery for Shu.`);toast(`${target.name} captured!`)}else{target.troops=Math.max(500,Math.floor(target.troops*.68));source.troops=Math.max(350,source.troops+Math.floor(commitment*.16));addLog(`<b>The assault on ${target.name} falters.</b> Your forces withdraw in disorder.`);toast('The attack is repelled.')}game.selected=targetId;render();checkEnd()}
function endTurn(){if(game.ended)return;game.turn++;game.season=(game.season+1)%4;if(game.season===0)game.year++;let count=ownCities().length;game.gold+=count*32;game.grain+=count*48;ownCities().forEach(c=>{c.grain=Math.max(0,c.grain-12);if(c.troops<8000&&c.grain>30&&Math.random()<.22)c.troops+=200});if(game.grain<0)game.grain=0;let event;if(game.turn%4===0){const enemies=game.cities.filter(c=>c.faction!=='Shu');const victim=enemies.find(c=>Math.abs(c.x-city('hanzhong').x)+Math.abs(c.y-city('hanzhong').y)<30);if(victim&&Math.random()<.42){const target=ownCities().find(c=>Math.abs(c.x-victim.x)+Math.abs(c.y-victim.y)<35);if(target){const loss=Math.min(target.troops-400,Math.floor(350+Math.random()*350));target.troops=Math.max(400,target.troops-loss);event=`<b>Border skirmish:</b> ${victim.general}'s forces raid ${target.name}; ${Math.max(0,loss).toLocaleString()} soldiers are lost.`}else event='Scouts report renewed movement in the north.'}else event='The realm is unsettled, but no armies march this season.'}else event=`Your commanderies bring in <b>${count*32} silver</b> and <b>${count*48} grain</b>. The people look to their lord for peace.`;document.getElementById('eventStrip').innerHTML=`<span class="spark">✦</span><span><b>${seasons[game.season]} dispatch</b> — ${event}</span>`;addLog(event);render();checkEnd()}
function checkEnd(){if(ownCities().length===8){finish(true)}else if(ownCities().length===0){finish(false)}}
function finish(win){game.ended=true;document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="crest">${win?'漢':'☯'}</div><div class="eyebrow">${win?'THE REALM IS UNITED':'THE HAN DYNASTY ENDS'}</div><h2>${win?'A New Emperor':'Your banner falls'}</h2><p>${win?'Through virtue and courage, Liu Bei has united the commanderies and restored peace to the realm. The people will remember this age.':'The last Shu stronghold has fallen. The chronicle will remember your attempt to restore the Han.'}</p><button class="primary" onclick="location.reload()">Begin a new chronicle</button></div></div>`}
function setTab(tab){game.activeTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let message={realm:'Realm overview selected.',army:`You command ${ownCities().length} garrisons. Select a friendly city to recruit or march.`,court:'Your sworn brothers Guan Yu and Zhang Fei stand ready to serve.',diplomacy:'Envoys can persuade rival commanderies to join your cause.'}[tab];toast(message);if(tab==='army'){const first=ownCities()[0];if(first)selectCity(first.id)}}
document.getElementById('endTurn').onclick=endTurn;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
addLog('<b>Liu Bei establishes his banner</b> in Chengdu. The road to unification begins.');render();
</script>
</body>
</html>

