const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'], headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.screenshot({ path: '/tmp/opencode/game-latest.jpg', type: 'jpeg', quality: 82 });
  const initial = await page.evaluate(() => ({
    title: document.title,
    cityButtons: document.querySelectorAll('#provinceLayer button').length,
    initialRecruitDisabled: document.querySelector('[data-action="recruit"]').disabled,
    initialText: document.querySelector('#resources').innerText.replace(/\s+/g, ' ').trim()
  }));
  await page.getByRole('button', { name: /Recruit troops/ }).click();
  const afterRecruit = await page.evaluate(() => ({ gold: game.gold, grain: game.grain, troops: city('chengdu').troops }));
  await page.getByRole('button', { name: /Develop city/ }).click();
  await page.getByRole('button', { name: /Improve farms/ }).click();
  const afterDevelopFarm = await page.evaluate(() => ({ gold: game.gold, grain: game.grain, localGrain: city('chengdu').grain, wealth: city('chengdu').wealth }));
  await page.getByRole('button', { name: /March army/ }).click();
  const marchPromptVisible = await page.locator('#actionNote').innerText();
  await page.getByRole('button', { name: /Jiangling/ }).click();
  const afterMarch = await page.evaluate(() => ({ faction: city('jiangling').faction, troops: city('jiangling').troops, shuCities: ownCities().length, selected: game.selected }));
  await page.getByRole('button', { name: /End Turn/i }).click();
  const afterTurn = await page.evaluate(() => ({ turn: game.turn, season: seasons[game.season], gold: game.gold, grain: game.grain }));
  console.log(JSON.stringify({ initial, afterRecruit, afterDevelopFarm, marchPromptVisible, afterMarch, afterTurn, errors }, null, 2));
  await browser.close();
})();

