  await page.locator('#mobileNav [data-tab="diplomacy"]').click();
  const mobile = await page.evaluate(() => ({
    viewport: innerWidth,
    documentWidth: document.documentElement.scrollWidth,
    mobileTabsVisible: getComputedStyle(document.querySelector('#mobileNav')).display !== 'none',
    activeTab: game.activeTab,
    actionButtons: [...document.querySelectorAll('#actionButtons button')].map(b => b.innerText.split('\n')[0])
  }));
  await page.screenshot({ path: '/tmp/opencode/game-latest.jpg', type: 'jpeg', quality: 82 });
  console.log(JSON.stringify({ envoy, mobile, errors }, null, 2));
